export function getModuloPorId(id: string): TrilhaModuloOficial | undefined {
  return TRILHAS_MODULOS_OFICIAIS.find(m => m.id === id);
}

export function getModuloPorNumero(numero: number): TrilhaModuloOficial | undefined {
  return TRILHAS_MODULOS_OFICIAIS.find(m => m.moduloNumero === numero);
}

export function getModulosPorArea(areaNome: string): TrilhaModuloOficial[] {
  const norm = areaNome.toLowerCase().trim();
  return TRILHAS_MODULOS_OFICIAIS.filter(m => 
    m.areas.some(a => a.toLowerCase().includes(norm)) ||
    m.disciplinasIds.some(d => d.toLowerCase().includes(norm))
  );
}

export function getProgressoGeralTrilhas(aulasConcluidasIds: Set<string>): {
  totalAulas: number;
  totalConcluidas: number;
  porcentagem: number;
} {
  const totalAulas = 3192;
  const totalConcluidas = aulasConcluidasIds.size;
  const porcentagem = Math.round((totalConcluidas / totalAulas) * 100);
  return { totalAulas, totalConcluidas, porcentagem };
}

export function getDisciplinasDoModulo(moduloId: string): string[] {
  const m = getModuloPorId(moduloId);
  return m ? m.disciplinasIds : [];
}
